from openpyxl.utils import range_boundaries
from openpyxl.utils.datetime import from_excel

input_path = "/mnt/data/spreadsheet/47741/1_47741_input.xlsx"
output_path = "/mnt/data/outputs/47741_0_e191e734/1_47741_output.xlsx"

