def to_date_value(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, date):
        return v
    if isinstance(v, (int, float)):
        return from_excel(v).date()
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        # Try common date text formats
        for fmt in ("%m/%d/%Y", "%m/%d/%y", "%Y-%m-%d", "%Y-%m-%d %H:%M:%S"):
            try:
                return datetime.strptime(s, fmt).date()
            except ValueError:
                pass
        # Try Excel serial number stored as text
        try:
            return from_excel(float(s)).date()
        except Exception:
            return None
    return None

def clean_sheet_name(s):
    s = s.strip()
    if s.startswith("'") and s.endswith("'"):
        s = s[1:-1].replace("''", "'")
    return s

def split_sheet_ref(expr, default_ws):
    expr = expr.strip()
    if "!" in expr:
        sh, ref = expr.rsplit("!", 1)
        return clean_sheet_name(sh), ref
    return default_ws.title, expr

def clean_ref(ref):
    return ref.strip().replace("$", "")

def get_cell_or_range_values(wb_values, default_ws, expr):
    sh_name, ref = split_sheet_ref(expr, default_ws)
    ws = wb_values[sh_name]
    ref = clean_ref(ref)

    if ":" in ref:
        min_col, min_row, max_col, max_row = range_boundaries(ref)
        vals = []
        for row in ws.iter_rows(min_row=min_row, max_row=max_row, min_col=min_col, max_col=max_col):
            for cell in row:
                vals.append(cell.value)
        return vals
    else:
        return [ws[ref].value]

def split_top_level_args(s):
    args = []
    cur = []
    depth = 0
    in_str = False
    i = 0
    while i < len(s):
        ch = s[i]
        if ch == '"':
            cur.append(ch)
            # handle doubled quotes inside string
            if in_str and i + 1 < len(s) and s[i + 1] == '"':
                cur.append(s[i + 1])
                i += 1
            else:
                in_str = not in_str
        elif not in_str and ch in "({[":
            depth += 1
            cur.append(ch)
        elif not in_str and ch in ")}]":
            depth -= 1
            cur.append(ch)
        elif not in_str and ch == "," and depth == 0:
            args.append("".join(cur).strip())
            cur = []
        else:
            cur.append(ch)
        i += 1
    if cur or s.endswith(","):
        args.append("".join(cur).strip())
    return args

def extract_function_calls(formula, func_name):
    calls = []
    pattern = re.compile(r"\b" + re.escape(func_name) + r"\s*\(", re.IGNORECASE)
    for m in pattern.finditer(formula):
        start = m.end()
        depth = 1
        in_str = False
        i = start
        while i < len(formula):
            ch = formula[i]
            if ch == '"':
                if in_str and i + 1 < len(formula) and formula[i + 1] == '"':
                    i += 1
                else:
                    in_str = not in_str
            elif not in_str:
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth == 0:
                        calls.append(formula[start:i])
                        break
            i += 1
    return calls

def eval_numbers_from_expr(wb_values, default_ws, expr):
    expr = expr.strip()
    nums = []

    # Array constants such as {10,12}
    if expr.startswith("{") and expr.endswith("}"):
        inner = expr[1:-1]
        parts = re.split(r"[,;]", inner)
        for p in parts:
            p = p.strip()
            if p:
                nums.append(float(p))
        return nums

    # Direct number
    try:
        return [float(expr)]
    except Exception:
        pass

    # Cell or range reference
    if re.match(r"^('?[^']+'?|[A-Za-z0-9_ ]+!)?\$?[A-Za-z]{1,3}\$?\d+(:\$?[A-Za-z]{1,3}\$?\d+)?$", expr.strip()):
        vals = get_cell_or_range_values(wb_values, default_ws, expr)
        for v in vals:
            if isinstance(v, (int, float)):
                nums.append(float(v))
            elif isinstance(v, str):
                try:
                    nums.append(float(v.strip()))
                except Exception:
                    pass
        if nums:
            return nums

    # Last-resort numeric extraction
    found = re.findall(r"[-+]?\d+(?:\.\d+)?", expr)
    return [float(x) for x in found]

def workday(start_dt, days, holidays):
    days = int(days)
    if days == 0:
        return start_dt

    step = 1 if days > 0 else -1
    remaining = abs(days)
    cur = start_dt
    holiday_set = set(h for h in holidays if h is not None)

    while remaining:
        cur += timedelta(days=step)
        if cur.weekday() < 5 and cur not in holiday_set:
            remaining -= 1
