wb = load_workbook(input_path, data_only=False)
wb_values = load_workbook(input_path, data_only=True)
ws = wb[sheet_name]
ws_values = wb_values[sheet_name]

formula = ws[target_cell].value
computed_text = None

if isinstance(formula, str) and formula.startswith("="):
    workday_calls = extract_function_calls(formula, "WORKDAY")
    result_dates = []

    for call in workday_calls:
        args = split_top_level_args(call)
        if len(args) >= 2:
            start_expr = args[0]
            days_expr = args[1]
            holidays_expr = args[2] if len(args) >= 3 else ""

            start_vals = get_cell_or_range_values(wb_values, ws_values, start_expr)
            start_dt = to_date_value(start_vals[0]) if start_vals else None

            days_list = eval_numbers_from_expr(wb_values, ws_values, days_expr)

            holidays = []
            if holidays_expr:
                for hv in get_cell_or_range_values(wb_values, ws_values, holidays_expr):
                    hd = to_date_value(hv)
                    if hd is not None:
                        holidays.append(hd)

            if start_dt is not None:
                for n in days_list:
                    result_dates.append(workday(start_dt, n, holidays))

    if result_dates:
        computed_text = "-".join(f"{d:%m/%d/%Y}" for d in result_dates)

# Fallback: convert the existing cached serial-number range in B5 if formula parsing is not available.
if computed_text is None:
    cached_value = wb_values[sheet_name][target_cell].value
    computed_text = convert_serial_range_text(cached_value)

# Final fallback based on the formula in the prompt/layout.
if computed_text is None:
    start_dt = to_date_value(ws_values["B4"].value)
    holidays = [to_date_value(ws_values[f"K{r}"].value) for r in range(14, 21)]
    result_dates = [workday(start_dt, n, holidays) for n in (10, 12)]
